function withTempDir<R>(body: (dir: string) => R): R {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'job-'));
  try {
    return body(dir);                 // body typed to the resource
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

