import { openSync, closeSync } from 'node:fs';

class Handle implements Disposable {                 // standard interface
  constructor(private readonly fd: number) {}
  [Symbol.dispose](): void { closeSync(this.fd); }
}

function run(path: string): void {
  using handle = new Handle(openSync(path, 'r'));   // disposed on scope exit
  readAll(handle);
}
